// Builds the Aseprite and Pixel Art curriculum.
//
// Source: scripts/curriculums/aseprite.md, which is the plan. The material is
// in aseprite-detail.json and the cards are in aseprite-cards.json, for the
// reasons japanese.mjs gives: prose full of tables does not belong inside a JS
// template literal, and cards are data rather than prose.
//
// A REWRITE, NOT A REVISION. The first version (2026-10-09) was 8 stages and
// 64 lessons with a median of about 426 characters of material each -- an index
// of exercises rather than a course -- on the pre-Greek machinery, with a flat
// list of lesson strings, no per-lesson sources and no deck.
//
// HIS FOUR RULINGS, 2026-10-14:
//   1. The whole craft, with the contract as the GATE rather than the scope.
//      Pixel art zero to mastery, taught throughout on Shepherds, and an asset
//      is accepted by design/art-and-animation.md section 10.
//   2. All four asset classes -- characters and creatures, terrain and
//      architecture, props and set-pieces, UI art and VFX. The first version
//      covered the first and touched the rest only inside "Production".
//   3. A card deck, unlike Godot: the subject has a great deal of assertable
//      material. A judgement call is not a card.
//   4. FREE WEB RESOURCES ONLY. The ~25 art books on the machine are reserved
//      for the Drawing curriculum that follows this one.
//
// THE LESSON NAMES CHANGE KIND. The first version's names were the exercises
// ("50 clean one-pixel lines at every angle"). That belongs in the practice at
// the foot of a lesson. A title says what the lesson is about.
//
// EVERY GEOMETRY NUMBER IS QUOTED FROM THE CONTRACT, with its section named so
// the claim can be checked: 960x540, 112x112, pivot (56, 96), ~80 px adult,
// 16 px tile, 8 px subgrid, 45.7 px per metre, 24 frames, 12 fps, 12 frames.
//
// AND THE MOST USEFUL MATERIAL CAME FROM READING THE MACHINE, which is the
// method Godot's rewrite used. Aseprite Wizard 9.8.0 derives FPS as
// ceil(1000 / shortest frame duration in ms) with rounding on by default, so a
// frame at 83 ms -- the natural choice for 12 fps -- imports at 13 fps and 84 ms
// imports at 12. That is in no tutorial and no design document.
//
// Pinned: Aseprite 1.3.18.6, Aseprite Wizard 9.8.0, Godot 4.7, the contract as
// reset 2026-09-22, Palette v0.1 (132 entries, 33 ramps).
//
// Prints SQL. Nothing is executed here -- `npm run curriculum aseprite`.

import detail from './aseprite-detail.json' with { type: 'json' };
import cards from './aseprite-cards.json' with { type: 'json' };

const SOURCE = 'scripts/curriculums/aseprite.md';
const NAME = 'Aseprite and Pixel Art';

/** SQL single-quoted string. An apostrophe in a title ends the literal early. */
const q = (value) =>
  value === null || value === undefined ? 'null' : `'${String(value).replace(/'/g, "''")}'`;

const NOW = new Date().toISOString();
const CURRICULUM = `(select id from curriculums where name = ${q(NAME)})`;
/** The lesson just inserted. The other scripts use the same trick. */
const LESSON = '(select max(id) from lessons)';

/** Every key asked for, so a stray one in a data file can be found. */
const askedDetail = new Set();
const askedCards = new Set();
const missing = [];

function detailFor(name) {
  askedDetail.add(name);
  const text = detail[name];
  if (text === undefined) {
    // Loud rather than silent: a lesson renamed here and not in the data file
    // would otherwise quietly lose its material.
    missing.push(name);
    return null;
  }
  return text;
}

/**
 * A card's natural key, which is what the database matches on: curriculum,
 * kind and front. Two lessons claiming the same one is a silent bug -- the
 * insert is `where not exists`, so the second claim does not fail, it just
 * quietly re-points the card at the later lesson. Caught here instead.
 */
const claimed = new Map();
const twiceClaimed = [];

function cardsFor(name) {
  askedCards.add(name);
  const list = cards[name] ?? [];
  for (const card of list) {
    const key = `${card.kind}\u0000${card.front}`;
    if (claimed.has(key)) twiceClaimed.push([card.front, claimed.get(key), name]);
    else claimed.set(key, name);
  }
  return list;
}

/**
 * A lesson is either a bare name or [name, sources]. Sources are per-lesson
 * rows in `sources`; the curriculum's OWN list (lesson_id is null) is
 * dashboard-owned and no script regenerates it.
 */
const nameOf = (lesson) => (Array.isArray(lesson) ? lesson[0] : lesson);
const sourcesOf = (lesson) => (Array.isArray(lesson) ? (lesson[1] ?? []) : []);

